ProjectALife.DialogueShards["scenes_misc_9"] = {
{"s13_law_shift_board_010","shift",1,"reg=law|mood=sad|world=building",{1,"Shift board's still up on the wall, magnets and all",1,"Mabry days, Tolliver evenings, Combs midnights",1,"Two of them three ain't coming in, I move the magnets anyhow"}},
{"s13_law_knox4_solo_022","shift",2,"reg=law|mood=fear",{1,"Knox 4, you got anybody with you?",2,"Negative - it's me",1,"Then you do not go in that house - you hear me? You wait on somebody",2,"Who? Say a name - say one name and I'll sit right here and wait on him"}},
{"s13_law_no_backup_032","shift",2,"reg=law|mood=fear|world=door",{1,"Twelve years and I never once cleared a house by myself",2,"How many today?",1,"Four, and I hollered before every door like a damn fool, 'cause it's all I got left of doing it right"}},
{"s13_ksp_no_backup_027","shift",2,"reg=law|role=law_trooper|mood=fear",{1,"Closest unit to me is in the next county and he ain't answering",2,"So what do you do on a bad one?",1,"I do it, and I say what I'm doing out loud on the air so there's a record of a man trying"}},
{"s13_ksp_kid_trooper_028","shift",3,"reg=law|tmp=fresh|world=road",{1,"Boy came out of the academy in May, sixty days on the road",2,"How's he doing?",3,"I'm doing fine",1,"He's doing fine, he also asked me which form you use when there ain't a form",3,"There's usually a form, that's all I meant by it"}},
{"ordinary_socks","small_comforts",2,"reg=civilian,worker|st=friendly,neutral",{1,"When did socks become something worth thinking about?",2,"Right after the blisters",1,"I used to get angry when somebody gave me socks for Christmas",2,"You owe several aunts an apology"}},
{"ordinary_rain_memory","small_comforts",2,"reg=civilian,worker,family|st=neutral,friendly|world=building,rain",{1,"Remember sleeping through rain on a proper roof?",2,"Without worrying about the roof part?",1,"Exactly",2,"We didn't know how good we were at resting"}},
}
